SELECT ,
       mp.status AS signstatus,
       mp.checkintime

         JOIN meetingparticipants AS mp ON mp.meetingid = m.meetingid AND mp.employeeid = #{employeeid}
WHERE m.status = 0
  AND m.starttime < #{end}
  AND m.endtime > #{start}
ORDER BY m.starttime

SELECT 

WHERE m.status = 0
  AND m.roomid = #{roomid}
  AND m.starttime < #{end}
  AND m.endtime > #{start}
ORDER BY m.starttime
